INSERT INTO `cms_settings` VALUES ('about_page','{\"heroBadge\":\"Who We Are & What We Stand For\",\"heroTitle\":\"Empowering the Next Generation of\",\"heroTitleHighlight\":\"Global Leaders\",\"heroDescription\":\"Founded on the belief that world-class education transforms trajectories, FCC Global Education bridges ambitious international scholars with the world’s most prestigious universities through ethical, data-driven, and high-touch mentorship.\",\"stats\":{\"stat1Value\":\"25,000+\",\"stat1Label\":\"Students Placed Globally\",\"stat2Value\":\"98.6%\",\"stat2Label\":\"Verified Visa Success\",\"stat3Value\":\"850+\",\"stat3Label\":\"Direct Partner Universities\",\"stat4Value\":\"$14.2M+\",\"stat4Label\":\"Scholarships Won by Students\"},\"storyBadge\":\"Our Story\",\"storyTitle\":\"Built on Academic Integrity, Driven by Student Triumph\",\"storyParagraph1\":\"FCC Global Education began with a clear realization: international education counseling was broken. Most traditional agencies pushed students toward low-tier, commission-heavy private institutions without regard for academic fit or career trajectory.\",\"storyParagraph2\":\"We set out to create an elite advisory modeled on collegiate fellowship committees. By hiring counselors with degrees from Oxford, Harvard, LSE, and TUM, we brought deep academic rigor to the application process. Today, we stand as one of the most respected independent educational consultancies with official university representations and direct alumni chapters spanning 20+ countries.\",\"storyImage\":\"https://images.unsplash.com/photo-1522202176988-66273c2fd55f?auto=format&fit=crop&w=1000&q=80\",\"storyImageBadge\":\"Founded by International Academics\",\"storyImageCaption\":\"Over a decade of university admissions excellence across UK, USA, Canada, & Australia.\",\"storyPillars\":[{\"title\":\"Ethical Counsel\",\"description\":\"Zero commission steering. We recommend universities that truly align with your goals.\"},{\"title\":\"Audit-Grade Visas\",\"description\":\"Immigration specialists verify all financial dossiers before submission.\"}],\"missionTitle\":\"Our Mission\",\"missionDescription\":\"To democratize access to the world’s top educational institutions by providing rigorous profiling, uncompromised writing guidance, transparent visa compliance, and relentless scholarship advocacy for every deserving student.\",\"visionTitle\":\"Our Vision\",\"visionDescription\":\"To be the world’s most trusted overseas education authority, known for elevating students into global thinkers, innovative problem solvers, and lifelong alumni leaders in their host societies.\",\"valuesBadge\":\"Guiding Principles\",\"valuesTitle\":\"Our Non-Negotiable Values\",\"values\":[{\"id\":\"val-1\",\"title\":\"1. Absolute Transparency\",\"description\":\"Honest chances assessment. If a program is unrealistic or overpriced, we give you unfiltered truth, not false promises.\"},{\"id\":\"val-2\",\"title\":\"2. Academic Rigor\",\"description\":\"We treat every application like an academic submission, ensuring essays are intellectually rich and free of boilerplate clichés.\"},{\"id\":\"val-3\",\"title\":\"3. Zero Plagiarism\",\"description\":\"Every personal statement is crafted from original student interviews and verified via Turnitin and AI-detection tools.\"},{\"id\":\"val-4\",\"title\":\"4. Lifelong Support\",\"description\":\"Our care extends well past the airport gate into local housing, tax registration, and graduate job hunting.\"}],\"teamBadge\":\"Expert Advisory Council\",\"teamTitle\":\"Meet Our Senior Counselors & Visa Directors\",\"teamDescription\":\"Our counselors possess real credentials from the world’s leading universities and legal immigration bodies.\",\"showTeam\":true,\"ctaBadge\":\"Begin Your Journey Today\",\"ctaTitle\":\"Connect Directly with a Senior Admissions Counselor\",\"ctaDescription\":\"Schedule a personalized, one-on-one session to evaluate your transcripts and identify matched universities with high scholarship likelihood.\",\"ctaPrimaryButtonText\":\"Book Free Profile Evaluation\",\"ctaPrimaryButtonLink\":\"/book-appointment\",\"ctaSecondaryButtonText\":\"View Our Services\",\"ctaSecondaryButtonLink\":\"/services\",\"seoTitle\":\"About Us | FCC Global Education Consultants\",\"seoDescription\":\"Learn about FCC Global Education’s story, leadership, global university accreditations, ethical counseling values, and 98.6% visa approval track record.\"}','2026-10-12 11:39:22'),('appointments','{\"availableDays\":[\"Monday\",\"Tuesday\",\"Wednesday\",\"Thursday\",\"Friday\",\"Saturday\"],\"workingHoursStart\":\"10:00 AM\",\"workingHoursEnd\":\"06:00 PM\",\"slotDurationMinutes\":30,\"timeZone\":\"Europe/London (GMT)\",\"defaultMeetingLink\":\"https://meet.google.com/aur-aglb-edu\",\"consultationTypes\":[\"Free Initial Profile Evaluation\",\"University Selection & Profiling\",\"Visa & Compliance Consultation\",\"Scholarship & Financial Aid Strategy\"]}','2026-10-04 18:26:17'),('email','{\"senderName\":\"AuraGlobal Admissions\",\"senderEmail\":\"admissions@auraglobal.com\",\"replyToEmail\":\"support@auraglobal.com\",\"smtpHost\":\"smtp.mailtrap.io\",\"smtpPort\":587,\"adminNotificationEmail\":\"admin@auraglobal.com\"}','2026-10-04 18:26:17'),('footer','{\"companyDescription\":\"AuraGlobal is a premier global education consultancy guiding students toward top-tier university placements and visa approvals.\",\"disclaimer\":\"Official partner and authorized recruitment representative for leading institutions in the UK, USA, Canada, Australia, and Europe.\",\"copyright\":\"© 2026 AuraGlobal Education Consultants. All rights reserved.\",\"newsletterText\":\"Subscribe to get bi-weekly university deadline reminders and scholarship alerts.\",\"quickLinks\":[{\"name\":\"About AuraGlobal\",\"href\":\"/about\"},{\"name\":\"Admissions Services\",\"href\":\"/services\"},{\"name\":\"Student Visa Guidance\",\"href\":\"/visa-success\"},{\"name\":\"Success Stories\",\"h