sApp\",\"whatsappNumber\":\"+442079460912\",\"selectorTitle\":\"Select Service to Inspect:\",\"portfolioBadge\":\"Complete Portfolio\",\"portfolioTitle\":\"Explore All Specialized Advisory Services\",\"portfolioSubtitle\":\"Every service is led by certified specialists with direct experience in university admissions and international immigration law.\",\"serviceCtaText\":\"Get Service Consultation\",\"serviceCtaLink\":\"/book-appointment\",\"ctaBadge\":\"Tailored Mentorship JU\",\"ctaTitle\":\"Not Sure Which Service You Need First?\",\"ctaDescription\":\"Book a complimentary 30-minute diagnostic session. Our senior counselor will evaluate your profile and chart a custom roadmap covering all required services.\",\"ctaButtonText\":\"Book Free Diagnostic Session\",\"ctaButtonLink\":\"/book-appointment\"}','2026-10-12 05:00:49'),('social','{\"facebook\":\"https://facebook.com/auraglobaledu\",\"instagram\":\"https://instagram.com/auraglobaledu\",\"youtube\":\"https://youtube.com/@auraglobaledu\",\"tiktok\":\"https://tiktok.com/@auraglobaledu\",\"linkedin\":\"https://linkedin.com/company/auraglobaledu\",\"whatsapp\":\"https://wa.me/447946091200\",\"twitter\":\"https://x.com/auraglobaledu\"}','2026-10-04 18:26:17'),('subscribers','[{\"id\":\"sub_1791813792293_dhdxq\",\"email\":\"opopopop@gmail.com\",\"name\":\"Muhammad Irfan fayyaz\",\"source\":\"contact\",\"status\":\"active\",\"subscribedAt\":\"2026-10-12T14:03:12.293Z\",\"phone\":\"03235502570\"},{\"id\":\"sub_1791813455502_5o3o0\",\"email\":\"irfanseoexpert420@gmail.com\",\"name\":\"Muhammad Irfan fayyaz\",\"source\":\"appointment\",\"status\":\"active\",\"subscribedAt\":\"2026-10-12T13:57:35.502Z\",\"phone\":\"+923235502570\"},{\"id\":\"sub_apt_apt-1\",\"email\":\"alex.wright@example.com\",\"name\":\"Alexander Wright\",\"source\":\"appointment\",\"status\":\"active\",\"subscribedAt\":\"2026-10-04T18:34:17.000Z\",\"phone\":\"+44 7700 900542\"},{\"id\":\"sub_apt_apt-2\",\"email\":\"tanya.sharma@example.com\",\"name\":\"