",\"name\":\"Zainab Bibi\",\"source\":\"contact\",\"status\":\"active\",\"subscribedAt\":\"2026-10-04T18:34:03.000Z\",\"phone\":\"+923331122334\"},{\"id\":\"sub_lead_test_lead_1791138640013\",\"email\":\"hamza.khan@test.com\",\"name\":\"Hamza Khan\",\"source\":\"contact\",\"status\":\"active\",\"subscribedAt\":\"2026-10-04T18:30:40.000Z\",\"phone\":\"+92 300 1234567\"}]','2026-10-12 14:28:46'),('visa_success_page','{\"heroBadge\":\"Verified Legal Immigration Compliance\",\"heroTitle\":\"Turning Study Dreams Into\",\"heroTitleHighlight\":\"Visa Success\",\"heroDescription\":\"Our certified immigration solicitors and visa compliance officers audit every bank statement, tax filing, and sponsor affidavit before submission, ensuring near-perfect approval outcomes.\",\"stats\":{\"stat1Value\":\"98.7%\",\"stat1Label\":\"Audited Visa Approval Rate\",\"stat2Value\":\"5,000+\",\"stat2Label\":\"Approved Student Visas\",\"stat3Value\":\"12+\",\"stat3Label\":\"Destination Consulates & Embassies\",\"stat4Value\":\"0%\",\"stat4Label\":\"Refusal on Compliant Files\"},\"galleryBadge\":\"Real Proofs & Official Stamps\",\"galleryTitle\":\"Verified Student Visa Approval Letters\",\"galleryDescription\":\"Browse genuine visa grant decisions and embassy approval stamps obtained by our scholars across the UK, USA, Canada, Australia, Germany, and Europe.\",\"frameworksBadge\":\"Country-Wise Protocols\",\"frameworksTitle\":\"Destination Visa Frameworks & Timelines\",\"frameworksDescription\":\"Every country enforces distinct financial holding rules, attestation mandates, and interview procedures. Here is how our team manages them for you.\",\"destinationFrameworks\":[{\"country\":\"United Kingdom\",\"flag\":\"??\",\"visaType\":\"United Kingdom Student Route Visa\",\"approvalRate\":\"97.6%\",\"avgProcessing\":\"2 – 4 Weeks via Official Portal\",\"fundsRule\":\"Proof of liquid living funds + tuition receipt\",\"interviewReq\":\"Comprehensive Credibility & Mock Interview Clinic\",\"keyHighlight\":\"Post-Study Work: 2-3 Years Graduate Route\"},{\"country\":\"United States\",\"flag\":\"??\",\"visaType\":\"United States F-1 Student Visa\",\"approvalRate\":\"95.4%\",\"avgProcessing\":\"3 – 6 Weeks via Official Portal\",\"fundsRule\":\"First year tuition + living funds on I-20\",\"interviewReq\":\"Mandatory Consular Interview Prep & Mocks\",\"keyHighlight\":\"Post-Study Work: 1-3 Years STEM OPT\"},{\"country\":\"Canada\",\"flag\":\"??\",\"visaType\":\"Canada Study Permit Route\",\"approvalRate\":\"96.2%\",\"avgProcessing\":\"4 – 8 Weeks via Official Portal\",\"fundsRule\":\"GIC CAD $20,635 + First Year Tuition Proof\",\"interviewReq\":\"SOP Documentation Review & Biometrics\",\"keyHighlight\":\"Post-Study Work: Up to 3 Years PGWP\"},{\"country\":\"Australia\",\"flag\":\"??\",\"visaType\":\"Subclass 500 Student Visa\",\"approvalRate\":\"97.8%\",\"avgProcessing\":\"3 – 6 Weeks via Official Portal\",\"fundsRule\":\"Living costs AUD $29,710 + First Year Tuition\",\"interviewReq\":\"GS (Genuine Student) Statement Audit\",\"keyHighlight\":\"Post-Study Work: 2-4 Years Post-Study Work\"},{\"country\":\"Germany\",\"flag\":\"??\",\"visaType\":\"Germany National Student Visa\",\"approvalRate\":\"99.1%\",\"avgProcessing\":\"4 – 8 Weeks via Official Portal\",\"fundsRule\":\"Blocked Account (€11,904) + Health Insurance\",\"interviewReq\":\"Embassy Document Verification Clinic\",\"keyHighlight\":\"Post-Study Work: 18 Months Job Seeking Permit\"}],\"auditBadge\":\"Why We Maintain 98.6% Success\",\"auditTitle\":\"Our 5-Stage Visa Pre-Audit Protocol\",\"auditDescription\":\"We never submit a visa application until it has cleared every internal compliance hurdle.\",\"auditStages\":[{\"stageNumber\":\"Stage 01\",\"title\":\"CAS / I-20 Audit\",\"description\":\"Verification that course start dates, fees, and passport details match academic records with zero discrepancies.\"},{\"stageNumber\":\"Stage 02\",\"title\":\"Financial Dossier Check\",\"description\":\"28-day holding verification, sponsor affidavits, CA valuation, and tax return audits.\"},{\"stageNumber\":\"Stage 03\",\"title\":\"Statement of Purpose\",\"description\":\"Legal drafting of SOP proving academic continuity, home ties, and genuine temporary student intent.\"},{\"stageNumber\":\"Stage 04\",\"title\":\"Consular Mocks\",\"description\":\"3 live 1-on-1 mock interviews simulating toughest questions on financing, post-study goals, and career progression.\"},{\"stageNumber\":\"Stage 05\",\"title\":\"Filing & Biometrics\",\"description\":\"Portal upload, VFS appointment booking, priority processing dispatch, and tracking until stamp collection.\"}],\"disclaimerTitle\":\"Compliance Disclosure & Realistic Advisory Notice\",\"disclaimerText\":\"FCC Global Education operates in strict compliance with international student recruitment standards. While our rigorous document audit produces an industry-leading 98.6% approval record, all visa grant determinations are the sole, sovereign prerogative of respective government immigration departments (such as UKVI, US Department of State, IRCC Canada, and Australian Home Affairs). We do not guarantee visa issuance; rather, we provide audit-standard representation that eliminates procedural and documentary refusal grounds.\",\"ctaTitle\":\"Have an Offer Letter and Need Flawless Visa Support?\",\"ctaDescription\":\"Book a dedicated visa consultation with our licensed immigration compliance director. We audit your financial documents and organize your mock interview clinic.\",\"ctaButtonText\":\"Book Visa File Assessment\"}','2026-10-11 09:06:07');
