CREATE TABLE `countries` (
  `id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `flag` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `region` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hero_image` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tagline` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `overview` text COLLATE utf8mb4_unicode_ci,
  `why_study` longtext COLLATE utf8mb4_unicode_ci,
  `popular_courses` longtext COLLATE utf8mb4_unicode_ci,
  `average_tuition` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `living_costs` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `currency` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `intakes` longtext COLLATE utf8mb4_unicode_ci,
  `post_study_work` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `visa_success_rate` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `work_while_studying` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `top_university_names` longtext COLLATE utf8mb4_unicode_ci,
  `scholarships_overview` text COLLATE utf8mb4_unicode_ci,
  `visa_requirements` longtext COLLATE utf8mb4_unicode_ci,
  `post_study_opportunities` longtext COLLATE utf8mb4_unicode_ci,
  `application_deadlines` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int(11) DEFAULT '1',
  `published` tinyint(1) DEFAULT '1',
  `seo_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_description` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_slug` (`slug`),
  KEY `idx_published` (`published`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
