INSERT INTO `countries` VALUES ('australia','australia','Australia','??','AU','Asia-Pacific','https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?auto=format&fit=crop&w=1600&q=80','World Top-Ranked Group of Eight & Spectacular Lifestyle','Australia is famed for its prestigious Group of Eight (Go8) research universities, high standard of living, and thriving multinational job market. Offering post-study work rights, generous minimum wage safeguards, and an enviable outdoor lifestyle, Australia attracts over half a million international students every year.','[\"7 Australian universities rank in the QS Global Top 100, including Melbourne, Sydney, and UNSW\",\"Subclass 485 Temporary Graduate Visa provides generous post-study work rights\",\"World-leading hourly minimum wage ($24.10+ AUD) protects international student part-time employment\",\"Safe, sunny, and cosmopolitan cities with pristine beaches and vibrant cultural scenes\",\"Pioneering research facilities in renewable energy, biotechnology, quantum computing, and mining\"]','[\"Information Technology & Cybersecurity\",\"Professional Accounting & FinTech\",\"Mining & Renewable Energy Engineering\",\"Nursing & Occupational Therapy\",\"Data Analytics & Enterprise Systems\",\"Marine Biology & Environmental Science\"]','AUD $25,000 – $45,000 / year','AUD $1,400 – $2,200 / month','AUD ($)','[\"Semester 1 (February / March - Main)\",\"Semester 2 (July / August - Main)\",\"Term 3 (November - Select)\"]','2 to 4 Years Post-Higher Education Work Stream (Subclass 485)','97.1%','48 hours per fortnight during study semesters; unlimited during holidays','[\"The University of Melbourne\",\"The University of Sydney\",\"The University of New South Wales (UNSW)\",\"Australian National University (ANU)\",\"Monash University\",\"The University of Queensland\",\"The University of Western Australia\",\"The University of Adelaide\"]','Australia Awards, Destination Australia Scholarships, Vice-Chancellor’s International Excellence Scholarships (20–50% tuition reduction).','[\"Confirmation of Enrolment (CoE) from registered CRICOS institution\",\"Genuine Student (GS) assessment questionnaire showing verified academic career progression\",\"Overseas Student Health Cover (OSHC) for the full visa duration\",\"Financial evidence of at least 1 year living expenses plus remaining tuition\",\"English proficiency (IELTS, PTE, or TOEFL)\"]','[\"Pathways through Subclass 189 / 190 skilled migration streams\",\"Strong regional migration bonuses in Adelaide, Perth, Brisbane, and Gold Coast\",\"High employer demand in healthcare, aged care, software, and construction\"]','Semester 1: Oct–Nov; Semester 2: April–May',4,1,NULL,NULL,'2026-10-04 18:26:16','2026-10-04 18:26:16'),('canada','canada','Canada','??','CA','North America','https://images.unsplash.com/photo-1517935703635-271905454b30?auto=format&fit=crop&w=1600&q=80','High Quality of Life, Welcoming Society & Clear Immigration Pathways','Canada combines world-class universities with a globally celebrated safety index, multicultural society, and student-centric post-graduation work permits (PGWP) of up to 3 years. Canadian credentials are internationally respected and offer clear bridges to permanent residency through Express Entry.','[\"Post-Graduation Work Permit (PGWP) allows graduates to gain valuable Canadian work experience for up to 3 years\",\"Affordable tuition compared to other major English-speaking destinations with high ROI\",\"Safe, welcoming, and diverse cities consistently ranked in the top 10 most livable worldwide\",\"Strong co-op and paid internship programs integrated into degree curriculums\",\"Clear Express Entry and Provincial Nominee Program (PNP) pathways for skilled international graduates\"]','[\"Software Engineering & Cloud Computing\",\"Business Administration & Supply Chain\",\"Health Informatics & Nursing\",\"Civil & Environmental Engineering\",\"Digital Marketing & Media Production\",\"Hospitality & Tourism Management\"]','CAD $18,000 – $38,000 / year','CAD $1,100 – $1,800 / month','CAD ($)','[\"Fall (September - Primary)\",\"Winter (January - Secondary)\",\"Summer (May - Select programs)\"]','Up to 3 Years open Post-Graduation Work Permit (PGWP)','96.2%','20 hours/week off-campus during terms, full-time during scheduled study breaks','[\"University of Toronto\",\"McGill University\",\"University of British Columbia (UBC)\",\"University of Alberta\",\"McMaster University\",\"University of Waterloo\",\"Western University\",\"Queen’s University\"]','Vanier Canada Graduate Scholarships, Ontario Graduate Scholarship, University President’s International Scholar Awards.','[\"Provincial Attestation Letter (PAL) and official Letter of Acceptance (LOA) from DLI\",\"Guaranteed Investment Certificate (GIC) of required living expense deposit\",\"Proof of first-year tuition payment receipt\",\"Medical clearance and police character certificate\",\"Comprehensive Statement of Purpose (SOP) demonstrating study trajectory\"]','[\"Direct Canadian Experience Class (CEC) eligibility under Express Entry\",\"Rapidly growing tech corridors in Toronto, Vancouver, Montreal, and Calgary\",\"High average graduate starting salaries in engineering and IT\"]','Fall: Dec 15–March 1; Winter: Sept 1–Nov 1',3,1,NULL,NULL,'2026-10-04 18:26:16','2026-10-04 18:26:16'),('finland','finland','Finland','??','FI','Europe','https://images.unsplash.com/photo-1517411032315-54ef2cb783bb?auto=format&fit=crop&w=1600&q=80','World’s Happiest Country & 2-Year Post-Study Jobseeker Visa','Ranked the Happiest Country in the World for 7 consecutive years, Finland offers an egalitarian, student-centered education system. International students enjoy an incredible 2-year post-study residence permit, 30 hours/week working rights, and strong tech ecosystem ties.','[\"Consistently ranked #1 Happiest Country in the World with unbeatable safety and clean air\",\"Generous 2-year post-study residence permit for job seeking, valid up to 5 years after graduating\",\"30 hours/week part-time work rights during studies (increased from 25 hours)\",\"Direct pathway: time spent on a continuous student residence permit counts 50% toward permanent residency\",\"Leading technology hub in 5G/6G, gaming (Rovio, Supercell), and clean technologies\"]','[\"Mobile & 6G Telecommunications\",\"Game Design & Interactive Technologies\",\"Clean Energy & Circular Bioeconomy\",\"International Business Management\",\"Software Engineering & Cloud Architectures\"]','€8,000 – €16,000 / year','€700 – €1,100 / month','EUR (€)','[\"Autumn (August / September - Primary)\",\"Spring (January - Limited)\"]','2-Year Post-Graduation Jobseeker Residence Permit','98.1%','30 hours per week during term-time','[\"University of Helsinki\",\"Aalto University\",\"Tampere University\",\"University of Oulu\",\"LUT University\",\"University of Turku\"]','Finland Scholarship (funded by Finnish Ministry of Education, covers 100% first-year tuition + €5,000 relocation grant), University Merit Waivers (50–100%).','[\"Certificate of Admission from Finnish University via Studyinfo.fi\",\"Proof of financial sustenance (€560/month or €6,720/year)\",\"Private health insurance policy covering medical treatments up to €40,000–€120,000\",\"Tuition fee payment receipt\"]','[\"Fast progression to Permanent Residence (P permit) — continuous student permit years count towards the 4-year requirement\",\"Huge industrial partnerships with Nokia, Wärtsilä, Kone, and game studios\"]','Joint Application Period: Early January for Autumn semester',12,1,NULL,NULL,'2026-10-04 18:26:16','2026-10-04 18:26:16'),('france','france','France','??','FR','Europe','https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=1600&q=80','Art, High Fashion, Elite Grandes Écoles & 5-Year Alumni Visas','France is renowned for its world-leading business schools, engineering Grandes Écoles, and subsidized student lifestyle. Under new bilateral agreements, Indian and international alumni of French universities enjoy 5-year short-stay Schengen visas.','[\"Top-tier Grandes Écoles consistently topping FT European Business School rankings (HEC Paris, INSEAD, ESSEC)\",\"Government-subsidized student accommodation (CAF allowance) cutting rent costs by up to 40%\",\"Over 1,700 English-taught degree programs across management, fashion, tech, and aerospace\",\"Exclusive 5-year short-stay circulation visa for master’s degree alumni\",\"Rich cultural heritage, gastronomy, and central access to all Schengen capitals\"]','[\"Luxury Brand Management & Fashion\",\"Master in Management (MiM) & MBA\",\"Aerospace Engineering & Robotics\",\"Culinary Arts & Hospitality Management\",\"Artificial Intelligence & Applied Maths\"]','€3,770 (Public Universities) – €18,000 / year (Grandes Écoles)','€800 – €1,400 / month (Paris higher)','EUR (€)','[\"Fall (September / October)\",\"Spring (January / February)\"]','2 Years APS (Autorisation Provisoire de Séjour) / RECE permit for Master’s graduates','96.8%','Up to 964 hours per year (60% of normal working year)','[\"Sorbonne University\",\"HEC Paris\",\"École Polytechnique (Institut Polytechnique de Paris)\",\"Sciences Po Paris\",\"ESSEC Business School\",\"Université Paris-Saclay\"]','Eiffel Excellence Scholarship, Charpak Scholarships (India), France Excellence Europa.','[\"Etudes en France (Campus France) verification and EEF interview\",\"Attestation d’inscription (admission letter) from school\",\"Proof of minimum €615/month financial support\",\"Proof of accommodation in France for the first 3 months\"]','[\"Passeport Talent (Talent Passport) for qualified researchers and corporate hires\",\"Booming startup ecosystem at Station F in Paris\"]','Campus France: Nov 15–Dec 15; Direct School: Nov–June',7,1,NULL,NULL,'2026-10-04 18:26:16','2026-10-04 18:26:16'),('germany','germany','Germany','??','DE','Europe','https://images.unsplash.com/photo-1467269204594-9661b134dd2b?auto=format&fit=crop&w=1600&q=80','Tuition-Free Public Universities & Europe’s Economic Powerhouse','Germany is Europe’s industrial and technological engine. Public universities charge almost zero tuition fees for international students, offering cutting-edge engineering, computing, and business degrees taught in English, supported by an 18-month job-seeker visa after graduation.','[\"Zero or low tuition fees at public universities across 15 of 16 German federal states\",\"Engineering and technical prowess: home to TU9, BMW, Siemens, SAP, and BASF\",\"18-month post-study work visa (Jobseeker Residence Permit) upon graduation\",\"Over 2,000 international degree programs fully taught in English\",\"EU Blue Card eligibility with fast-track permanent residency within 21–27 months\"]','[\"Automotive & Mechanical Engineering\",\"Artificial Intelligence & Informatics\",\"Renewable Energy & Power Systems\",\"International Management & Supply Chain\",\"Molecular Bioengineering\",\"Architecture & Urban Planning\"]','€0 – €3,000 / year (Nominal semester fee €150–€350)','€934 – €1,200 / month (Blocked Account: €11,904/year)','EUR (€)','[\"Winter Semester (October - Primary)\",\"Summer Semester (April - Secondary)\"]','18 Months post-study work residence permit to secure qualified employment','97.8%','140 full days or 280 half days per calendar year','[\"Technical University of Munich (TUM)\",\"Ludwig Maximilian University of Munich (LMU)\",\"Heidelberg University\",\"RWTH Aachen University\",\"Karlsruhe Institute of Technology (KIT)\",\"Free University of Berlin\",\"Humboldt University of Berlin\"]','DAAD Scholarships, Deutschlandstipendium (€300/month), Heinrich Böll Foundation grants.','[\"Official Letter of Admission or uni-assist preliminary documentation\",\"Blocked Account (Sperrkonto) with minimum required German statutory sum\",\"Proof of statutory or private German health insurance (e.g. TK, Barmer, or Mawista)\",\"German or English language certificate (IELTS/TestDaF/Goethe depending on language of instruction)\",\"Aps Certificate (for select nationalities)\"]','[\"Direct conversion to EU Blue Card with lowered salary thresholds for STEM fields\",\"Huge talent shortage across IT, mechanical engineering, and healthcare sectors\",\"Freedom of movement across the entire Schengen Zone\"]','Winter: May 1–July 15; Summer: Dec 1–Jan 15',5,1,NULL,NULL,'2026-10-04 18:26:16','2026-10-04 18:26:16'),('ireland','ireland','Ireland','??','IE','Europe','https://images.unsplash.com/photo-1590089415225-401ed6f9db8e?auto=format&fit=crop&w=1600&q=80','European Tech Hub, Only Native English-Speaking EU Nation','Ireland is the only English-speaking member of the Eurozone and acts as the European headquarters for Google, Apple, Meta, Pfizer, and Microsoft. Its universities offer 1-year master’s programs and an automatic 2-year Third Level Graduate Scheme visa.','[\"European Headquarters for 9 of the top 10 global software companies and US tech giants\",\"Automatic 2-year post-study work visa for Master’s and PhD graduates (Third Level Graduate Scheme)\",\"Only native English-speaking nation within the European Union\",\"Rich literary and academic traditions led by Trinity College Dublin and UCD\",\"High starting graduate salaries and fast pathways to Critical Skills Employment Permits\"]','[\"Cloud Computing & Big Data Analytics\",\"Pharmaceutical Science & Biotechnology\",\"Financial Technology (FinTech)\",\"Digital Marketing & Business Strategy\",\"Biomedical Engineering\"]','€11,000 – €26,000 / year','€1,000 – €1,600 / month','EUR (€)','[\"Autumn (September - Main)\",\"Spring (January - Select courses)\"]','24 Months (Master’s graduates) / 12 Months (Bachelor’s)','98.2%','20 hours/week during term, 40 hours/week during June–September and Christmas','[\"Trinity College Dublin (TCD)\",\"University College Dublin (UCD)\",\"University of Galway\",\"University College Cork (UCC)\",\"Dublin City University (DCU)\",\"University of Limerick\"]','Government of Ireland International Education Scholarships (Full tuition + €10,000 stipend), Global Excellence Scholarships.','[\"Letter of Acceptance from recognized Irish higher education institution\",\"Proof of fees paid to university (minimum €6,000 or full amount)\",\"Evidence of sufficient funds (€10,000 minimum readily accessible)\",\"Private medical insurance coverage\",\"English language certification (IELTS 6.5+ or equivalent)\"]','[\"Transition to 2-year Critical Skills Employment Permit leading to Stamp 4 permanent residency\",\"Direct recruitment events from Dublin’s \\\"Silicon Docks\\\"\"]','Rolling admissions: February to June',6,1,NULL,NULL,'2026-10-04 18:26:16','2026-10-04 18:26:16'),('italy','italy','Italy','??','IT','Europe','https://images.unsplash.com/photo-1529260830199-42c24126f198?auto=format&fit=crop&w=1600&q=80','Heritage, World-Class Design, Medicine & Regional DSU Scholarships','Italy is home to the world’s oldest university and world-leading institutions in architecture, automotive design, medicine, and engineering. With regional scholarships (DSU) providing free tuition and living stipends based on family income, studying in Italy is extraordinarily accessible.','[\"Regional DSU Scholarships can cover 100% of university tuition fees plus provide €7,000+ yearly living stipends\",\"World-famous programs in Architecture, Industrial Design, Automotive Engineering, and Medicine (IMAT)\",\"Home to the historic University of Bologna (founded 1088) and prestigious Politecnico di Milano\",\"Affordable cost of living in historic cities like Turin, Bologna, Padua, and Milan\",\"1-year post-study search permit for master’s and PhD graduates\"]','[\"Architecture & Urban Planning\",\"Automotive & Mechanical Design\",\"Medicine & Surgery (IMAT in English)\",\"Fashion Design & Luxury Goods\",\"Economics & Sustainable Development\"]','€1,000 – €4,000 / year (Public) / Free with DSU','€700 – €1,100 / month','EUR (€)','[\"Autumn (September / October - Main)\",\"Spring (Limited)\"]','12 Months \"Permesso di soggiorno per ricerca lavoro\" (Job Search Permit)','95.9%','20 hours/week, maximum 1,040 hours/year','[\"Politecnico di Milano\",\"University of Bologna\",\"Sapienza University of Rome\",\"University of Padua\",\"Bocconi University\",\"Politecnico di Torino\"]','Regional DSU Scholarships (income-based, up to full ride + stipend), MAECI Italian Government Scholarships, Invest Your Talent in Italy.','[\"Pre-enrolment summary via Universitaly portal approved by Italian University\",\"Declaration of Value (DoV) or CIMEA Statement of Comparability\",\"Proof of financial sustenance (€6,000+ per year)\",\"Health insurance policy covering minimum €30,000 emergencies in Schengen\"]','[\"Conversion of study permit to Work Permit (Permesso di Soggiorno per Lavoro Subordinato)\",\"Global prestige in design studios, luxury automotive (Ferrari, Ducati, Lamborghini), and pharmaceuticals\"]','Universitaly pre-enrolment: March to June',8,1,NULL,NULL,'2026-10-04 18:26:16','2026-10-04 18:26:16'),('netherlands','netherlands','Netherlands','??','NL','Europe','https://images.unsplash.com/photo-1512470876302-972faa2aa9a4?auto=format&fit=crop&w=1600&q=80','Leading English Taught Hub & 1-Year Search Year (Zoekjaar) Visa','The Netherlands was the first non-English speaking country to offer degree courses taught entirely in English. Known for problem-based learning, high tolerance, cycling culture, and the \"Zoekjaar\" (Orientation Year) visa, it provides a seamless pathway into the European tech and trade economy.','[\"Over 2,100 degree programs taught 100% in English with over 95% of Dutch citizens fluent in English\",\"Orientation Year (Zoekjaar) allows graduates to work without a work permit for 1 full year\",\"High-ranking research universities: Delft, Amsterdam, Erasmus Rotterdam, Utrecht\",\"Strategic European logistics and tech gateway (ASML, Philips, Booking.com, ING)\",\"Progressive, safe, and bike-friendly student cities with international communities\"]','[\"Computer Science & Microelectronics\",\"International Business & Econometrics\",\"Civil & Hydraulic Engineering\",\"Agriculture & Food Technology (Wageningen)\",\"Psychology & Cognitive Neuroscience\"]','€9,000 – €20,000 / year','€1,000 – €1,500 / month','EUR (€)','[\"September (Main)\",\"February (Select universities)\"]','1 Year Zoekjaar (Orientation Year) for recent graduates (can be taken within 3 years of graduating)','98.5%','16 hours/week with work permit, or full-time during June, July, and August','[\"Delft University of Technology (TU Delft)\",\"University of Amsterdam (UvA)\",\"Utrecht University\",\"Erasmus University Rotterdam\",\"Eindhoven University of Technology\",\"Leiden University\"]','NL Scholarship (formerly Holland Scholarship, €5,000), Erasmus+ Grants, University Excellence Scholarships.','[\"University applies for your MVV entry visa and VVR residence permit directly with IND\",\"Proof of financial means (approx. €12,200/year deposited with university)\",\"Legalized and translated academic certificates\",\"Valid passport and TB test upon arrival (if applicable)\"]','[\"Highly Skilled Migrant (Kennismigrant) visa with reduced salary threshold for Zoekjaar graduates\",\"Home to semiconductor monopoly ASML, global fintech hubs, and international maritime trade\"]','Numerus Fixus: Jan 15; Regular: April 1–May 1',9,1,NULL,NULL,'2026-10-04 18:26:16','2026-10-04 18:26:16'),('new-zealand','new-zealand','New Zealand','??','NZ','Asia-Pacific','https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1600&q=80','Safe Haven, World Top 3% Universities & Up to 3-Year Post-Study Visa','All eight New Zealand universities rank in the QS World Top 500. Known for stunning landscapes, unmatched safety, welcoming Maori hospitality, and post-study work visas for up to 3 years, New Zealand provides an exceptional quality of education and lifestyle.','[\"100% of New Zealand universities rank in the top 3% worldwide\",\"Post-Study Work Visa granted for up to 3 years for eligible degree qualifications\",\"Consistently ranked #1 or #2 globally on the Global Peace Index\",\"Masters and PhD students pay domestic fees for PhDs and their spouses can get full-time open work visas\",\"High demand for skilled graduates in civil engineering, healthcare, agriculture, and IT\"]','[\"Environmental Science & Ecology\",\"Agribusiness & Viticulture\",\"Civil & Structural Engineering\",\"Data Science & Software Development\",\"Tourism & Hospitality Management\"]','NZD $26,000 – $42,000 / year','NZD $1,400 – $2,000 / month','NZD ($)','[\"Semester 1 (February / March - Main)\",\"Semester 2 (July - Main)\"]','Up to 3 Years Post-Study Work Visa (duration matching degree level)','96.5%','20 hours/week during term, full-time during vacations','[\"The University of Auckland\",\"University of Otago\",\"Victoria University of Wellington\",\"University of Canterbury\",\"Massey University\",\"University of Waikato\"]','New Zealand International Excellence Scholarships, Manaaki New Zealand Scholarships, University of Auckland International Student Excellence.','[\"Offer of Place from NZQA-accredited education provider\",\"Proof of sufficient funds (NZD $20,000/year living funds plus tuition)\",\"Chest X-ray and medical examination\",\"Police clearance certificate\"]','[\"Straight to Residence and Work to Residence pathways under Green List occupations\",\"Spousal full-time work visa rights during post-graduate studies\"]','Semester 1: Nov–Dec; Semester 2: April–May',10,1,NULL,NULL,'2026-10-04 18:26:16','2026-10-04 18:26:16'),('sweden','sweden','Sweden','??','SE','Europe','https://images.unsplash.com/photo-1509356843151-3e7d96241e11?auto=format&fit=crop&w=1600&q=80','Home of the Nobel Prize, Sustainability & Tech Unicorns (Spotify, Klarna)','Sweden is the birthplace of the Nobel Prize and a pioneer in sustainability, design, and tech innovation. International students benefit from team-based, critical-thinking education and a 1-year residence permit to seek employment or start a business post-graduation.','[\"Birthplace of global unicorns: Spotify, Klarna, Mojang (Minecraft), Skype, and King\",\"12-month post-study residence permit to find work or explore startup ventures\",\"World-leading focus on green technology, sustainability, and renewable circular economy\",\"Top institutions: KTH Royal Institute of Technology, Lund University, Uppsala University\",\"No legal limit on the number of hours international students can work while studying\"]','[\"Sustainable Energy & CleanTech\",\"Information & Communication Technology\",\"Industrial Design & Ergonomics\",\"Biomedicine & Molecular Medicine\",\"Global Public Health\"]','SEK 90,000 – 170,000 / year (approx. €8,000–€15,000)','SEK 9,500 – 13,000 / month','SEK (kr)','[\"Autumn (August / September - Primary)\",\"Spring (January - Limited)\"]','12 Months residence permit after completed higher education to seek employment','97.2%','Unlimited hours permitted as long as full-time academic progress is maintained','[\"KTH Royal Institute of Technology\",\"Lund University\",\"Uppsala University\",\"Chalmers University of Technology\",\"Karolinska Institute\",\"Stockholm University\"]','Swedish Institute Scholarships for Global Professionals (full tuition + monthly SEK 12,000 living allowance), University Tuition waivers.','[\"Letter of Acceptance via UniversityAdmissions.se\",\"Tuition fee first installment payment confirmed by Swedish university\",\"Proof of financial means (SEK 10,314/month for living expenses)\",\"Comprehensive health insurance policy\"]','[\"Fast-track Swedish work permit after obtaining a job offer meeting union standard salary\",\"Progress to permanent residency after 4 years of work permit status\"]','First Admission Round: Jan 15 for Autumn semester',11,1,NULL,NULL,'2026-10-04 18:26:16','2026-10-04 18:26:16'),('uk','uk','United Kingdom','??','GB','Europe','https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?auto=format&fit=crop&w=1600&q=80','World-Leading Heritage, 1-Year Master Degrees & Global Prestige','The United Kingdom boasts some of the oldest and most prestigious universities in the world. With globally recognized qualifications, cutting-edge research infrastructure, and the Graduate Route Visa offering 2 years of post-study work, the UK remains the premier choice for ambitious international scholars.','[\"Shorter degree duration: 3-year Bachelor’s and 1-year Master’s programmes save both time and living expenses\",\"Home to 4 of the world’s top 10 universities (QS World University Rankings)\",\"The Graduate Route Visa permits international students to work in the UK for at least 2 years post-graduation (3 years for PhD)\",\"Rich multicultural student community with over 680,000 international students\",\"Extensive NHS healthcare coverage and student welfare support systems\"]','[\"Business Analytics & Finance\",\"Data Science & Artificial Intelligence\",\"Law & International Dispute Resolution\",\"Mechanical & Aerospace Engineering\",\"Biomedical Sciences & Public Health\",\"Creative Media & Architecture\"]','£14,000 – £32,000 / year','£1,015 – £1,334 / month (London: £1,334+)','GBP (£)','[\"September / October (Major)\",\"January / February (Secondary)\",\"May (Select courses)\"]','2 Years (Graduate Route) / 3 Years for PhD graduates','98.6%','20 hours/week during term-time, full-time during official vacation periods','[\"University of Oxford\",\"University of Cambridge\",\"Imperial College London\",\"University College London (UCL)\",\"University of Manchester\",\"University of Edinburgh\",\"King’s College London\",\"University of Warwick\"]','Chevening Scholarships, Commonwealth Scholarships, GREAT Scholarships, and university-specific merit bursaries of up to £10,000 off tuition.','[\"Confirmation of Acceptance for Studies (CAS) from a licensed UK sponsor\",\"Financial proof demonstrating maintenance funds for 9 months plus outstanding tuition\",\"IELTS / PTE Academic or approved UKVI English proficiency\",\"Tuberculosis (TB) test certificate from an approved clinic\",\"Valid passport with at least 6 months validity\"]','[\"Fast progression to Skilled Worker Visa sponsorship upon securing eligible employment\",\"Global financial and tech capital access in London, Manchester, and Edinburgh\",\"World-class professional certifications (ACCA, CIPD, RIBA, GMC)\"]','UCAS Undergraduate: 15 Oct (Oxbridge/Med) / 29 Jan (Equal Consideration). Postgraduate: Rolling (April–July recommended)',1,1,NULL,NULL,'2026-10-04 18:26:16','2026-10-04 18:26:16'),('usa','usa','United States','??','US','North America','https://images.unsplash.com/photo-1485738422979-f5c462d49f74?auto=format&fit=crop&w=1600&q=80','Innovation Capital, Ivy League Excellence & 3-Year STEM OPT','The United States is the epicenter of global higher education, hosting more top 100 universities than any other nation. From Silicon Valley engineering to Wall Street finance, US universities blend academic rigor with world-changing internships and up to 3 years of post-graduation STEM OPT work rights.','[\"Unrivaled research funding and world-leading faculty in technology, AI, and biotech\",\"Flexible academic system allowing students to explore double majors and switch concentrations\",\"Up to 36 months of Optional Practical Training (STEM OPT extension) for qualifying degree programs\",\"Massive campus ecosystems with state-of-the-art labs, sports arenas, and alumni networks\",\"Generous merit scholarships, TA/RA assistantships, and on-campus fellowships\"]','[\"Computer Science & Machine Learning\",\"MBA & Quantitative Finance\",\"Biomedical Engineering & Robotics\",\"Data Analytics & Information Systems\",\"Liberal Arts & Global Governance\",\"Cybersecurity & Cloud Computing\"]','$22,000 – $55,000 / year','$1,200 – $2,200 / month','USD ($)','[\"Fall (August / September - Primary)\",\"Spring (January - Secondary)\",\"Summer (Limited)\"]','1 Year standard OPT + 24 Month STEM extension (3 Years Total)','95.4%','20 hours/week on-campus during academic sessions, 40 hours/week during holidays','[\"Harvard University\",\"Massachusetts Institute of Technology (MIT)\",\"Stanford University\",\"Columbia University\",\"University of California, Berkeley\",\"University of Michigan\",\"New York University (NYU)\",\"Carnegie Mellon University\"]','Fulbright Foreign Student Program, University Merit Fellowships, Graduate Assistantships (covering 50-100% tuition + stipend).','[\"Form I-20 issued by SEVP-certified institution and paid SEVIS I-901 fee\",\"DS-160 visa application confirmation and scheduled embassy interview\",\"Proof of liquid financial capability to fund at least the first academic year\",\"Academic transcripts, standardized test scores (GRE/GMAT/SAT where applicable), and TOEFL/IELTS\",\"Strong ties to home country demonstrating non-immigrant intent\"]','[\"Direct pathway from STEM OPT to H-1B specialty occupation sponsorship\",\"Unmatched recruitment by Fortune 500 tech, biotech, banking, and consulting giants\",\"Campus startup incubators and VC funding access\"]','Early Action/Decision: Nov 1–15; Regular Decision: Jan 1–Feb 1; Grad: Dec–Feb',2,1,NULL,NULL,'2026-10-04 18:26:16','2026-10-04 18:26:16');
