INSERT INTO `custom_pages` VALUES ('page-privacy','privacy-policy','Privacy Policy','https://images.unsplash.com/photo-1450133064473-71024230f91b?q=80&w=1200','### AuraGlobal Education - Privacy Policy\n\nWe prioritize student privacy and comply with global GDPR regulations.',1,'Privacy Policy | AuraGlobal Education','Official privacy policy of AuraGlobal Education Consultants.','2026-10-04 18:26:17','2026-10-04 18:26:17'),('page-terms','terms-and-conditions','Terms & Conditions','https://images.unsplash.com/photo-1450133064473-71024230f91b?q=80&w=1200','### Terms & Conditions\n\nAll advisory and admissions consultancy terms of engagement.',1,'Terms & Conditions | AuraGlobal Education','Official terms and conditions of AuraGlobal Education.','2026-10-04 18:26:17','2026-10-04 18:26:17');
