INSERT INTO `team_members` VALUES ('team-1','Dr. Evelyn Montgomery','Founder & Chief Executive Officer','18+ Years in International Higher Education','[\"PhD in International Education (Oxford)\",\"Former Admissions Dean\",\"PIER Certified (QEAC)\"]','https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=600&q=80','Former senior admissions evaluator at top UK and Canadian institutions with nearly two decades of experience guiding over 4,000 students to world-class academic institutions.','[\"Oxbridge Admissions\",\"Institutional Strategy\",\"Global Scholarships\"]',1,1,'2026-10-04 18:26:17','2026-10-04 18:26:17'),('team-2','Julian Vance, Esq.','Director of Global Immigration & Visa Compliance','14+ Years in Immigration Law','[\"LL.M. International Law (LSE)\",\"OISC Level 3 Regulated\",\"Former Consular Officer Advisor\"]','https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=600&q=80','Specialist in student visa jurisprudence across the UK, USA, Australia, and the Schengen zone. Oversees our 98.6% visa approval audit pipeline and interview preparation clinics.','[\"US F-1 Visa Credibility\",\"UKVI CAS Compliance\",\"Financial Dossier Auditing\"]',2,1,'2026-10-04 18:26:17','2026-10-04 18:26:17'),('team-3','Samantha Rao','Head of North American Admissions (USA & Canada)','11+ Years in US/Canada College Counseling','[\"M.Ed. Higher Education (Harvard)\",\"NACAC Member\",\"AIRC Certified Counselor\"]','https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=600&q=80','Helped place hundreds of scholars into Ivy League and top Canadian universities with over $8 million in institutional scholarships and graduate assistantships.','[\"Ivy League Admissions\",\"STEM OPT Extensions\",\"Common App Strategy\"]',3,1,'2026-10-04 18:26:17','2026-10-04 18:26:17'),('team-4','Henrik Lindqvist','Head of European & Nordic Higher Education','9+ Years in Continental European Admissions','[\"M.Sc. Munich (TUM)\",\"DAAD Alumni Network\",\"Study in Sweden Certified\"]','https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=600&q=80','Pioneered zero-tuition German and regional Italian scholarship pathways for international students, with unmatched expertise in APS certification and uni-assist processing.','[\"Germany Tuition-Free Admissions\",\"APS Procedures\",\"DSU Scholarships Italy\"]',4,1,'2026-10-04 18:26:17','2026-10-04 18:26:17');
