INSERT INTO `universities` VALUES ('cambridge','cambridge','University of Cambridge','United Kingdom','uk','Cambridge, England',2,'QS World #2 | Global Top Tier','15.8%','https://images.unsplash.com/photo-1509062522246-3755977927d7?auto=format&fit=crop&w=200&q=80','https://images.unsplash.com/photo-1509062522246-3755977927d7?auto=format&fit=crop&w=1200&q=80','Founded in 1209, Cambridge is a global leader in scientific breakthroughs, mathematics, and humanities. Home to the Cavendish Laboratory and \"Silicon Fen\", Europe’s largest technology cluster.','{\"undergraduate\":\"£25,734 – £63,990 / year\",\"postgraduate\":\"£27,000 – £45,000 / year\"}','£1,250 – £1,750 / month','[\"Engineering Tripos\",\"Natural Sciences Tripos\",\"Master of Finance (MFin)\",\"Computer Science\",\"Law & Legal Studies\"]','[\"Engineering\",\"Computer Science\",\"Natural Sciences\",\"Finance & Business\",\"Law\"]','{\"academic\":\"A*A*A at A-Level (or 40–42 in IB with 776 at Higher Level). Masters: UK First Class Honors or equivalent (85%+ or 3.8+ GPA).\",\"english\":\"IELTS 7.5 (minimum 7.0 in all bands) or TOEFL 110 (25+ in all sections).\",\"standardizedTests\":\"College-specific written assessments & academic interview.\"}','[{\"title\":\"Gates Cambridge Scholarship\",\"amount\":\"Full cost of study + Maintenance allowance (£20,000/yr) + Airfare\",\"deadline\":\"Early December\",\"eligibility\":\"Outstanding intellectual ability, leadership, and commitment to improving others’ lives.\"},{\"title\":\"Cambridge Trust International Scholarship\",\"amount\":\"Full tuition fee + living stipend\",\"deadline\":\"January funding round\",\"eligibility\":\"Merit-based for international postgraduate scholars.\"}]','[\"October (Michaelmas Term)\"]','[\"121 Nobel Laureates affiliated with the University\",\"Heart of Europe’s Silicon Fen with over 5,000 tech companies\",\"Centuries-old collegiate rivalry with Oxford (\\\"The Varsity Match\\\")\"]',1,1,2,1,NULL,NULL,NULL,'2026-10-04 18:26:16','2026-10-04 18:26:16'),('harvard','harvard','Harvard University','United States','usa','Cambridge, Massachusetts',4,'Ivy League | Global Pioneer','3.4%','https://images.unsplash.com/photo-1562774053-701939374585?auto=format&fit=crop&w=200&q=80','https://images.unsplash.com/photo-1562774053-701939374585?auto=format&fit=crop&w=1200&q=80','Established in 1636, Harvard is the oldest higher education institution in the United States and member of the prestigious Ivy League. It boasts the world’s largest academic endowment and legendary faculty.','{\"undergraduate\":\"$57,261 / year\",\"postgraduate\":\"$52,000 – $78,000 / year (HBS / HLS)\"}','$1,800 – $2,600 / month','[\"Harvard Business School MBA\",\"Harvard Law School LLM / JD\",\"MS Computational Science and Engineering (SEAS)\",\"Master in Public Policy (Kennedy School)\",\"Biomedical Informatics\"]','[\"Business & Economics\",\"Law\",\"Computer Science\",\"Medicine\",\"Humanities\"]','{\"academic\":\"Near-perfect high school GPA (3.9+ unweighted) or undergraduate transcript (3.8+ GPA / First Class Honours).\",\"english\":\"TOEFL iBT 105+ or IELTS 7.5+.\",\"standardizedTests\":\"SAT / ACT for undergrad; GRE / GMAT for graduate programs.\"}','[{\"title\":\"Harvard Need-Blind Financial Aid (Undergraduate)\",\"amount\":\"100% Demonstrated Need Covered (Free tuition for family income <$85,000)\",\"deadline\":\"Regular Decision: Jan 1\",\"eligibility\":\"All admitted undergraduate students, including international applicants.\"}]','[\"August / September (Fall)\"]','[\"$50+ Billion endowment powering unrivaled lab resources\",\"Widener Library holding over 20 million items\",\"Historic Boston-Cambridge collegiate ecosystem\"]',0,1,6,1,NULL,NULL,NULL,'2026-10-04 18:26:17','2026-10-04 18:26:17'),('imperial','imperial','Imperial College London','United Kingdom','uk','London, England',6,'QS World #6 | #1 in Europe for STEM','12.9%','https://images.unsplash.com/photo-1523050854058-8df90110c9f1?auto=format&fit=crop&w=200&q=80','https://images.unsplash.com/photo-1523050854058-8df90110c9f1?auto=format&fit=crop&w=1200&q=80','Located in the heart of South Kensington, London, Imperial College London is exclusively dedicated to Science, Engineering, Medicine, and Business. Renowned for translating ground-breaking research into enterprise.','{\"undergraduate\":\"£35,100 – £45,000 / year\",\"postgraduate\":\"£34,000 – £42,500 / year\"}','£1,400 – £2,000 / month (London Zone 1–2)','[\"MSc Advanced Computing & Machine Learning\",\"Aeronautical Engineering\",\"MSc Financial Technology & Quantitative Risk\",\"Biomedical Engineering\",\"Imperial MBA\"]','[\"Engineering\",\"Computer Science\",\"Medicine\",\"Business & Economics\",\"Natural Sciences\"]','{\"academic\":\"A*A*A to A*AA in Mathematics and Sciences. For Masters: UK 2:1 or First Class (80%+ / 3.5+ GPA).\",\"english\":\"IELTS 7.0 (6.5 minimum in all elements) or Duolingo 125+.\",\"standardizedTests\":\"TMUA or ESAT for engineering candidates.\"}','[{\"title\":\"President’s PhD Scholarships\",\"amount\":\"Full tuition fee + £25,150 annual tax-free stipend\",\"deadline\":\"Rolling round deadlines (Nov, Jan, March)\",\"eligibility\":\"High-achieving students across the globe admitted to PhD programs.\"},{\"title\":\"Imperial Business School Dean’s Excellence Award\",\"amount\":\"Up to £20,000 fee reduction\",\"deadline\":\"Round 2 MBA deadline\",\"eligibility\":\"Demonstrated professional leadership and academic excellence.\"}]','[\"September / October\"]','[\"White City Innovation Hub with direct incubator funding for student startups\",\"Located adjacent to the Science Museum, Natural History Museum, and Hyde Park\",\"Top average starting salary of any UK university graduate body\"]',1,1,3,1,NULL,NULL,NULL,'2026-10-04 18:26:16','2026-10-04 18:26:16'),('manchester','manchester','University of Manchester','United Kingdom','uk','Manchester, England',32,'QS World #32 | Russell Group Leader','27.0%','https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=200&q=80','https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=1200&q=80','A historic powerhouse of innovation where the atom was first split and graphene was discovered. Manchester is the most targeted university by the UK’s leading graduate employers (High Fliers Research).','{\"undergraduate\":\"£24,000 – £34,500 / year\",\"postgraduate\":\"£26,000 – £35,000 / year\"}','£950 – £1,300 / month','[\"MSc Advanced Computer Science\",\"Alliance Manchester Business School MBA / Finance\",\"Mechanical & Aerospace Engineering\",\"Biotechnology & Genomics\",\"International Development\"]','[\"Engineering\",\"Computer Science\",\"Business & Economics\",\"Life Sciences\",\"Humanities\"]','{\"academic\":\"AAA to ABB at A Level. Masters: UK 2:1 honours degree or international equivalent.\",\"english\":\"IELTS 6.5–7.0 (no band less than 6.0).\"}','[{\"title\":\"Global Futures Scholarship\",\"amount\":\"Up to £8,000 tuition fee reduction\",\"deadline\":\"End of April\",\"eligibility\":\"Awarded to high-achieving international applicants.\"}]','[\"September\"]','[\"25 Nobel Laureates associated with the University\",\"Ranked #1 UK university targeted by top 100 employers\",\"Vibrant music, arts, and sports culture in dynamic Manchester\"]',1,1,5,1,NULL,NULL,NULL,'2026-10-04 18:26:17','2026-10-04 18:26:17'),('mcgill','mcgill','McGill University','Canada','canada','Montreal, Quebec',30,'QS World #30 | Canada’s Ivy','38.0%','https://images.unsplash.com/photo-1541339907198-e08756dedf3f?auto=format&fit=crop&w=200&q=80','https://images.unsplash.com/photo-1541339907198-e08756dedf3f?auto=format&fit=crop&w=1200&q=80','Often referred to as the \"Harvard of Canada\", McGill is situated at the foot of Mount Royal in multicultural Montreal. McGill boasts the highest average entering grades of any Canadian university.','{\"undergraduate\":\"CAD $31,000 – $61,000 / year\",\"postgraduate\":\"CAD $21,000 – $38,000 / year\"}','CAD $1,100 – $1,600 / month (Montreal is highly affordable)','[\"Computer Science & Software Engineering\",\"Desautels Faculty of Management (BCom / MBA)\",\"Neuroscience & Molecular Biology\",\"Mechanical Engineering\",\"Law (BCL / JD)\"]','[\"Computer Science\",\"Life Sciences\",\"Business & Economics\",\"Engineering\",\"Law\"]','{\"academic\":\"High school graduation with 85–92% in prerequisite subjects. Graduate: Minimum 3.2/4.0 GPA.\",\"english\":\"IELTS 6.5 (minimum 6.0 in each band) or TOEFL 90 (21 in each component).\"}','[{\"title\":\"Major Entrance Scholarships\",\"amount\":\"CAD $3,000 to $12,000 annually (renewable)\",\"deadline\":\"February 1\",\"eligibility\":\"Demonstrated top-tier academic excellence and civic leadership.\"},{\"title\":\"McCall MacBain Scholarships\",\"amount\":\"Full tuition and fees + CAD $2,000 monthly living stipend\",\"deadline\":\"Late August / September\",\"eligibility\":\"Comprehensive scholarship for master’s and professional degree candidates.\"}]','[\"September (Fall)\"]','[\"Montreal voted one of the world’s top student cities (QS Best Student Cities)\",\"Home to 12 Nobel Prize winners and 145 Rhodes Scholars\",\"Bilingual French/English cultural environment\"]',1,0,10,1,NULL,NULL,NULL,'2026-10-04 18:26:17','2026-10-04 18:26:17'),('melbourne','melbourne','The University of Melbourne','Australia','australia','Melbourne, Victoria',13,'QS World #13 | #1 in Australia','35.0%','https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=200&q=80','https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=1200&q=80','Established in 1853, the University of Melbourne is Australia’s #1 ranked university. Its distinctive Melbourne Curriculum provides broad foundation studies followed by specialized graduate degrees.','{\"undergraduate\":\"AUD $36,000 – $52,000 / year\",\"postgraduate\":\"AUD $38,000 – $55,000 / year\"}','AUD $1,500 – $2,300 / month','[\"Master of Information Technology\",\"Melbourne Business School MBA / Master of Management\",\"Master of Engineering (Software / Civil / Biomedical)\",\"Bachelor of Biomedicine\",\"Master of Data Science\"]','[\"Computer Science\",\"Business & Economics\",\"Engineering\",\"Life Sciences\",\"Architecture\"]','{\"academic\":\"Australian ATAR 85–98 equivalent (85%+ CBSE/ISC or 32+ IB). Masters: Equivalent of 65–75%+ WAM from recognized institution.\",\"english\":\"IELTS 6.5 overall (no band less than 6.0) or PTE 58.\"}','[{\"title\":\"Melbourne International Undergraduate Scholarship\",\"amount\":\"Up to 100% fee remission (valued at up to AUD $140,000)\",\"deadline\":\"Automatic assessment upon admission\",\"eligibility\":\"High achieving international undergraduate students.\"},{\"title\":\"Graduate Research Scholarships\",\"amount\":\"100% Tuition Fee waiver + AUD $37,000/year living allowance\",\"deadline\":\"October 31\",\"eligibility\":\"All domestic and international research students.\"}]','[\"February (Semester 1)\",\"July (Semester 2)\"]','[\"Located in Parkville, Melbourne’s renowned biomedical and research precinct\",\"Parkville campus just 10 minutes from Melbourne CBD\",\"Member of the prestigious Group of Eight (Go8) and Universitas 21\"]',1,0,11,1,NULL,NULL,NULL,'2026-10-04 18:26:17','2026-10-04 18:26:17'),('mit','mit','Massachusetts Institute of Technology (MIT)','United States','usa','Cambridge, Massachusetts',1,'QS World #1 Globally (13 Consecutive Years)','3.9%','https://images.unsplash.com/photo-1507679799987-c73779587ccf?auto=format&fit=crop&w=200&q=80','https://images.unsplash.com/photo-1507679799987-c73779587ccf?auto=format&fit=crop&w=1200&q=80','MIT is the undisputed world leader in science, engineering, and technology innovation. Known for its motto \"Mens et Manus\" (Mind and Hand), MIT fosters audacious problem solvers who transform industries.','{\"undergraduate\":\"$59,750 / year\",\"postgraduate\":\"$57,000 – $84,000 / year\"}','$1,900 – $2,700 / month','[\"Electrical Engineering and Computer Science (EECS)\",\"MIT Sloan Master of Finance & MBA\",\"Aerospace, Aeronautical & Astronautical Engineering\",\"Mechanical Engineering\",\"Artificial Intelligence & Robotics\"]','[\"Computer Science\",\"Engineering\",\"Business & Economics\",\"Natural Sciences\"]','{\"academic\":\"Top 1% academic percentile, deep STEM research and Olympiad achievements.\",\"english\":\"IELTS 7.5+ or TOEFL 100+.\",\"standardizedTests\":\"Mandatory SAT/ACT for UG; GRE for select grad programs.\"}','[{\"title\":\"MIT Need-Based Undergraduate Scholarship\",\"amount\":\"Full tuition + living assistance based on family income\",\"deadline\":\"February 15\",\"eligibility\":\"Need-blind admissions for international applicants.\"},{\"title\":\"MIT Graduate Research & Teaching Assistantships\",\"amount\":\"100% Tuition waiver + Monthly living stipend ($3,500+)\",\"deadline\":\"Program application deadline\",\"eligibility\":\"Admitted graduate PhD and MS thesis students.\"}]','[\"September (Fall)\"]','[\"101 Nobel laureates, 26 Turing Award winners\",\"Over 30,000 active companies founded by MIT alumni generating $2+ Trillion revenue\",\"Home to the famous MIT Media Lab and CSAIL\"]',1,0,7,1,NULL,NULL,NULL,'2026-10-04 18:26:17','2026-10-04 18:26:17'),('oxford','oxford','University of Oxford','United Kingdom','uk','Oxford, England',3,'QS World #3 | Times Higher Ed #1','14.2%','https://images.unsplash.com/photo-1541339907198-e08756dedf3f?auto=format&fit=crop&w=200&q=80','https://images.unsplash.com/photo-1541339907198-e08756dedf3f?auto=format&fit=crop&w=1200&q=80','The oldest university in the English-speaking world, Oxford is a collegiate research university with a unique tutorial teaching system. It has educated 30 British prime ministers, 55 Nobel Prize laureates, and 120 Olympic medalists.','{\"undergraduate\":\"£28,950 – £44,240 / year\",\"postgraduate\":\"£30,050 – £48,500 / year\"}','£1,290 – £1,840 / month','[\"Philosophy, Politics and Economics (PPE)\",\"Computer Science & Advanced Software\",\"MSc Financial Economics (MFE)\",\"Biomedical Sciences & Genetics\",\"Bachelor of Civil Law (BCL)\"]','[\"Business & Economics\",\"Computer Science\",\"Law\",\"Life Sciences\",\"Humanities\"]','{\"academic\":\"AAA to A*A*A at A-level (or 38–40 IB points / 90%+ in High School Board exams). For Masters: UK First Class or 2:1 equivalent (3.7+ CGPA).\",\"english\":\"IELTS Academic: 7.5 overall with minimum 7.0 in each sub-component (or TOEFL iBT 110).\",\"standardizedTests\":\"UCAT, LNAT, MAT, or TSA depending on undergraduate program.\"}','[{\"title\":\"Clarendon Fund Scholarships\",\"amount\":\"100% Tuition Fee + Annual Living Grant (£18,622)\",\"deadline\":\"December / January admissions deadline\",\"eligibility\":\"Outstanding academic merit and research potential; open to all nationalities.\"},{\"title\":\"Rhodes Scholarship\",\"amount\":\"Full university fees + living stipend + flights\",\"deadline\":\"Early October\",\"eligibility\":\"Exceptional young leaders demonstrating civic commitment and academic brilliance.\"}]','[\"October (Michaelmas Term)\"]','[\"World-famous one-on-one tutorial pedagogy\",\"38 historic constituent colleges with self-governing communities\",\"Bodleian Library housing over 13 million printed volumes\",\"Massive global alumni network with direct industry pipelines\"]',1,1,1,1,NULL,NULL,NULL,'2026-10-04 18:26:16','2026-10-04 18:26:16'),('stanford','stanford','Stanford University','United States','usa','Stanford, California',5,'QS World #5 | Silicon Valley Engine','3.6%','https://images.unsplash.com/photo-1541339907198-e08756dedf3f?auto=format&fit=crop&w=200&q=80','https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=1200&q=80','Located in the heart of Silicon Valley, Stanford is one of the world’s leading research and teaching institutions. Stanford alumni have founded Google, Yahoo, Nike, Hewlett-Packard, Sun Microsystems, and Netflix.','{\"undergraduate\":\"$61,731 / year\",\"postgraduate\":\"$58,000 – $79,000 / year\"}','$2,100 – $2,900 / month','[\"Computer Science (AI, Systems, Human-Computer Interaction)\",\"Stanford Graduate School of Business (GSB) MBA\",\"Bioengineering & Biotechnology\",\"Symbolic Systems\",\"Sustainable Energy Sciences\"]','[\"Computer Science\",\"Business & Economics\",\"Engineering\",\"Life Sciences\",\"Law\"]','{\"academic\":\"Unweighted GPA 3.9+, rigorous AP/IB courses, standout entrepreneurial impact.\",\"english\":\"TOEFL iBT 100+ (IELTS not preferred for undergraduate).\",\"standardizedTests\":\"GRE / GMAT for graduate programs.\"}','[{\"title\":\"Knight-Hennessy Scholars Program\",\"amount\":\"Full tuition + living stipend + travel grant for up to 3 years\",\"deadline\":\"Early October\",\"eligibility\":\"Graduate students with outstanding leadership and civic focus.\"}]','[\"September (Fall)\"]','[\"Sprawling 8,180-acre sunlit Mediterranean-style campus\",\"Unsurpassed access to Silicon Valley venture capital and tech founders\",\"Home to Stanford d.school (Hasso Plattner Institute of Design)\"]',1,0,8,1,NULL,NULL,NULL,'2026-10-04 18:26:17','2026-10-04 18:26:17'),('sydney','sydney','The University of Sydney','Australia','australia','Sydney, New South Wales',18,'QS World #18 | Top Group of Eight','30.0%','https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?auto=format&fit=crop&w=200&q=80','https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?auto=format&fit=crop&w=1200&q=80','Australia’s first university, founded in 1850. Consistently ranked among the top 20 universities worldwide and ranked #4 globally for graduate employability.','{\"undergraduate\":\"AUD $42,000 – $56,000 / year\",\"postgraduate\":\"AUD $44,000 – $54,000 / year\"}','AUD $1,600 – $2,400 / month','[\"Master of Commerce & Business Analytics\",\"Master of Computer Science (AI and Cloud)\",\"Sydney Law School LLM\",\"Biomedical Engineering & Mechatronics\",\"Master of Architecture\"]','[\"Business & Economics\",\"Computer Science\",\"Engineering\",\"Law\",\"Architecture\"]','{\"academic\":\"Australian ATAR 80–95 equivalent. Masters: Australian Bachelor’s degree or equivalent with minimum credit average (65%+).\",\"english\":\"IELTS 7.0 (minimum 6.0 in all bands) or PTE 68.\"}','[{\"title\":\"Vice-Chancellor’s International Scholarships Scheme\",\"amount\":\"Up to AUD $40,000 fee contribution\",\"deadline\":\"Automatic assessment with offer\",\"eligibility\":\"High-ranking international students across all programs.\"}]','[\"February (Semester 1)\",\"July (Semester 2)\"]','[\"Iconic neo-Gothic Quadrangle campus ranked among the world’s most beautiful\",\"Ranked #4 globally for graduate employability (QS Graduate Employability Rankings)\",\"Over 250 student clubs and societies\"]',1,0,12,1,NULL,NULL,NULL,'2026-10-04 18:26:17','2026-10-04 18:26:17'),('toronto','toronto','University of Toronto','Canada','canada','Toronto, Ontario',21,'QS World #21 | #1 in Canada','43.0%','https://images.unsplash.com/photo-1568792923760-d70635a89fa9?auto=format&fit=crop&w=200&q=80','https://images.unsplash.com/photo-1568792923760-d70635a89fa9?auto=format&fit=crop&w=1200&q=80','Canada’s flagship university, U of T has produced four Canadian prime ministers and 10 Nobel laureates. Renowned for its breakthroughs in artificial intelligence (Geoffrey Hinton), stem cells, and the discovery of insulin.','{\"undergraduate\":\"CAD $42,000 – $64,000 / year\",\"postgraduate\":\"CAD $28,000 – $52,000 / year\"}','CAD $1,400 – $2,100 / month','[\"MSc Applied Computing (MScAC)\",\"Rotman School of Management MBA / MFin\",\"Engineering Science & Robotics\",\"Life Sciences & Biotechnology\",\"Global Affairs (Munk School)\"]','[\"Computer Science\",\"Business & Economics\",\"Engineering\",\"Life Sciences\",\"Humanities\"]','{\"academic\":\"Minimum 85%+ in Class 12 / High School (Competitive programs: 92%+). Masters: Mid-B or B+ average in senior years (approx 3.3+ GPA).\",\"english\":\"IELTS 6.5 overall (minimum 6.0 in each band) or TOEFL 100.\"}','[{\"title\":\"Lester B. Pearson International Scholarship\",\"amount\":\"100% Tuition, books, incidental fees, and full residence support for 4 years\",\"deadline\":\"School nomination: Nov 30; Application: Dec 15\",\"eligibility\":\"Exceptional academic achievers and creative leaders nominated by their high schools.\"},{\"title\":\"International Scholar Award\",\"amount\":\"Up to CAD $100,000 ($25,000/year renewable)\",\"deadline\":\"Automatic consideration upon admission\",\"eligibility\":\"High-merit applicants across Arts & Science and Engineering faculties.\"}]','[\"September (Fall)\"]','[\"Three vibrant campuses across the Greater Toronto Area (St. George, Mississauga, Scarborough)\",\"Vector Institute partnership driving global AI development\",\"Ranked #1 in Canada for graduate employability\"]',1,0,9,1,NULL,NULL,NULL,'2026-10-04 18:26:17','2026-10-04 18:26:17'),('trinity-dublin','trinity-dublin','Trinity College Dublin','Ireland','ireland','Dublin, Ireland',81,'QS World #81 | #1 in Ireland','33.0%','https://images.unsplash.com/photo-1590089415225-401ed6f9db8e?auto=format&fit=crop&w=200&q=80','https://images.unsplash.com/photo-1590089415225-401ed6f9db8e?auto=format&fit=crop&w=1200&q=80','Founded in 1592 by Queen Elizabeth I, Trinity is Ireland’s historic flagship university. Located right in the heart of Dublin, adjacent to Silicon Docks and the European headquarters of major tech companies.','{\"undergraduate\":\"€20,600 – €37,600 / year\",\"postgraduate\":\"€18,000 – €27,000 / year\"}','€1,200 – €1,700 / month','[\"MSc Computer Science (Data Science / Future Networked Systems)\",\"Trinity Business School MSc Finance & Marketing\",\"Immunology & Global Health\",\"LLM International and Comparative Law\",\"Bioengineering\"]','[\"Computer Science\",\"Business & Economics\",\"Life Sciences\",\"Law\",\"Engineering\"]','{\"academic\":\"Class 12 / High School: 85–90%+. Masters: Minimum 2:1 Honours degree (60–65%+ in Indian/US curricula).\",\"english\":\"IELTS 6.5 overall (no band below 6.0) or TOEFL 90.\"}','[{\"title\":\"Global Excellence Postgraduate Scholarship\",\"amount\":\"€2,000 to €5,000 tuition fee deduction\",\"deadline\":\"March 31\",\"eligibility\":\"Assessed on academic achievement and potential contribution to Trinity.\"}]','[\"September (Autumn)\"]','[\"Famous 18th-century Old Library housing the Book of Kells\",\"Ranked #1 in Europe for producing venture-backed entrepreneurs for 7 straight years\",\"Located 15 minutes walk from Google, Meta, and Twitter EMEA headquarters\"]',1,0,14,1,NULL,NULL,NULL,'2026-10-04 18:26:17','2026-10-04 18:26:17'),('tum','tum','Technical University of Munich (TUM)','Germany','germany','Munich, Bavaria',28,'QS World #28 | #1 in Germany','8.0%','https://images.unsplash.com/photo-1467269204594-9661b134dd2b?auto=format&fit=crop&w=200&q=80','https://images.unsplash.com/photo-1467269204594-9661b134dd2b?auto=format&fit=crop&w=1200&q=80','TUM is Germany’s premier university of technology and entrepreneurship. Renowned for its direct partnerships with BMW, Audi, Siemens, and Airbus, producing game-changing tech leaders.','{\"undergraduate\":\"€2,000 – €3,000 / semester (International)\",\"postgraduate\":\"€4,000 – €6,000 / semester\"}','€1,000 – €1,400 / month (Munich)','[\"MSc Informatics / Computer Science\",\"MSc Automotive Engineering\",\"MSc Robotics, Cognition, Intelligence\",\"Master in Management & Technology (TUM-BWL)\",\"MSc Aerospace Engineering\"]','[\"Engineering\",\"Computer Science\",\"Business & Economics\",\"Natural Sciences\"]','{\"academic\":\"German Abitur equivalent or 4-year Bachelor’s in related engineering/STEM discipline with German Grade 1.5–2.0 (equivalent to 80%+).\",\"english\":\"IELTS 6.5+ or TOEFL 88+ (For English tracks); TestDaF for German tracks.\",\"standardizedTests\":\"TUM Aptitude Assessment / Academic Interview.\"}','[{\"title\":\"Deutschlandstipendium\",\"amount\":\"€300/month living subsidy\",\"deadline\":\"July 15\",\"eligibility\":\"Awarded to both incoming and current international students based on merit and engagement.\"}]','[\"October (Winter Semester - Primary)\",\"April (Summer Semester)\"]','[\"18 Nobel Prize laureates affiliated with TUM\",\"Unmatched corporate sponsorship with BMW, Siemens, and Google Munich Hub\",\"Vibrant startup incubator \\\"UnternehmerTUM\\\", Europe’s largest center for founders\"]',1,0,13,1,NULL,NULL,NULL,'2026-10-04 18:26:17','2026-10-04 18:26:17'),('ucl','ucl','University College London (UCL)','United Kingdom','uk','London, England',9,'QS World #9 | London’s Global University','15.0%','https://images.unsplash.com/photo-1541339907198-e08756dedf3f?auto=format&fit=crop&w=200&q=80','https://images.unsplash.com/photo-1541339907198-e08756dedf3f?auto=format&fit=crop&w=1200&q=80','London’s leading multidisciplinary university, UCL was founded in 1826 as the first university in England to admit students regardless of their religion and the first to admit women on equal terms.','{\"undergraduate\":\"£26,200 – £37,500 / year\",\"postgraduate\":\"£29,000 – £41,000 / year\"}','£1,350 – £1,950 / month','[\"MSc Data Science & Public Policy\",\"Architecture (The Bartlett School)\",\"MSc Management\",\"Law (LLM)\",\"Artificial Intelligence for Sustainable Development\"]','[\"Architecture\",\"Computer Science\",\"Business & Economics\",\"Law\",\"Life Sciences\"]','{\"academic\":\"A*AA – AAB at A level or 36–39 IB points. Masters: Minimum upper second-class Bachelor’s degree (60–65%+ in Indian/US curricula).\",\"english\":\"IELTS 7.0–7.5 depending on UCL English Level 1 to 5.\"}','[{\"title\":\"UCL Global Masters Scholarship\",\"amount\":\"£15,000 towards tuition\",\"deadline\":\"Early May\",\"eligibility\":\"Financial need and academic excellence for international students.\"}]','[\"September\"]','[\"The Bartlett School of Architecture ranked #1 in the world\",\"Campus located right in central Bloomsbury, steps from the British Museum\"]',1,1,4,1,NULL,NULL,NULL,'2026-10-04 18:26:17','2026-10-04 18:26:17');
